@namespace sv_2bc4e54152ce47509b086e57b12e6dc2.Components.Pages.Settings
@using sv_2bc4e54152ce47509b086e57b12e6dc2.Models

<div class="settings-section">
    <h3>Appearance</h3>
    <p class="text-muted">Customize the look and feel</p>
    <hr />

    @if (Settings is not null)
    {
        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="mb-4">
                    <h5>Theme</h5>
                    @foreach (var theme in themes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                   value="@theme" checked="@(selectedTheme == theme)"
                                   @onchange="() => selectedTheme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h5>Font Size</h5>
                    @foreach (var size in fontSizes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                   value="@size" checked="@(selectedFontSize == size)"
                                   @onchange="() => selectedFontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" style="max-width: 250px;" @bind="selectedLanguage">
                        @foreach (var lang in languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                    @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save
                </button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="appearance-preview @GetPreviewClasses()">
                    <div class="preview-header">
                        <strong>Preview</strong>
                    </div>
                    <div class="preview-body">
                        <p class="preview-title">Dashboard</p>
                        <p>Welcome back! Here's your summary for today.</p>
                        <div class="preview-card">
                            <span class="preview-stat">42</span>
                            <span class="preview-label">New messages</span>
                        </div>
                        <button class="btn btn-sm btn-primary mt-2">View Details</button>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }
    [Parameter] public EventCallback OnNotify { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;
    private bool saving;

    private static readonly string[] themes = ["Light", "Dark", "System"];
    private static readonly string[] fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override void OnParametersSet()
    {
        if (Settings is not null && !saving)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var cls = $"preview-theme-{selectedTheme.ToLowerInvariant()} preview-font-{selectedFontSize.ToLowerInvariant()}";
        if (compactMode) cls += " preview-compact";
        return cls;
    }

    private async Task SaveAsync()
    {
        saving = true;
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        await OnNotify.InvokeAsync();
        saving = false;
    }
}

