@page "/settings"
@rendermode InteractiveServer
@using sv_2bc4e54152ce47509b086e57b12e6dc2.Components.Pages.Settings
@using sv_2bc4e54152ce47509b086e57b12e6dc2.Models
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionSelected="s => activeSection = s" />

    <div class="settings-content">
        @if (loading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@profile"
                                    OnSave="SaveProfileAsync"
                                    OnNotify="() => ShowToast(\"Profile saved successfully!\")" />
                    break;

                case "Notifications":
                    <NotificationsSection Prefs="@notificationPrefs"
                                          OnSave="SaveNotificationPrefsAsync"
                                          OnNotify="() => ShowToast(\"Notification preferences saved!\")" />
                    break;

                case "Security":
                    <SecuritySection Security="@securitySettings"
                                     OnChangePassword="ChangePasswordAsync"
                                     OnRevokeSession="RevokeSessionAsync"
                                     OnNotify="() => ShowToast(\"Security settings updated!\")" />
                    break;

                case "Appearance":
                    <AppearanceSection Settings="@appearanceSettings"
                                       OnSave="SaveAppearanceAsync"
                                       OnNotify="() => ShowToast(\"Appearance settings saved!\")" />
                    break;
            }
        }
    </div>
</div>

@if (showToast)
{
    <div class="settings-toast">
        <div class="alert alert-success d-flex align-items-center shadow" role="alert">
            <span class="me-2">✓</span>
            @toastMessage
        </div>
    </div>
}

@code {
    private string activeSection = "Profile";
    private bool loading = true;
    private bool showToast;
    private string toastMessage = "";

    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        profile = await SettingsService.GetProfileAsync();
        notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        appearanceSettings = await SettingsService.GetAppearanceAsync();
        loading = false;
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationPrefsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task ChangePasswordAsync((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
    }

    private async Task ShowToast(string message)
    {
        toastMessage = message;
        showToast = true;
        StateHasChanged();
        await Task.Delay(3000);
        showToast = false;
        StateHasChanged();
    }
}

/* === Settings Dashboard Layout === */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 100px);
    gap: 0;
}

/* === Sidebar === */
.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 0.75rem;
    font-weight: 600;
    color: #495057;
    border-bottom: 1px solid #dee2e6;
    margin-bottom: 0.5rem;
}

.settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: all 0.15s;
}

.settings-sidebar .nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* === Content Area === */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 900px;
}

.settings-section h3 {
    margin-bottom: 0.25rem;
}

/* === Profile === */
.avatar-preview {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
}

.avatar-area > div {
    flex: 1;
}

/* === Appearance Preview === */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.2s;
}

.preview-header {
    padding: 0.5rem 1rem;
    border-bottom: 1px solid #dee2e6;
    font-size: 0.85rem;
}

.preview-body {
    padding: 1rem;
}

.preview-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.preview-card {
    background: #f0f0f0;
    padding: 0.75rem;
    border-radius: 6px;
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.preview-stat {
    font-size: 1.5rem;
    font-weight: 700;
    color: #0d6efd;
}

.preview-label {
    color: #6c757d;
    font-size: 0.85rem;
}

/* Theme variants */
.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-light .preview-header {
    background: #f8f9fa;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-theme-dark .preview-header {
    background: #181825;
    border-color: #45475a;
    color: #cdd6f4;
}

.preview-theme-dark .preview-card {
    background: #313244;
}

.preview-theme-dark .preview-label {
    color: #a6adc8;
}

.preview-theme-dark .btn-primary {
    background: #89b4fa;
    border-color: #89b4fa;
    color: #1e1e2e;
}

.preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
}

.preview-theme-system .preview-header {
    background: #f8f9fa;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 0.95rem;
}

.preview-font-large {
    font-size: 1.1rem;
}

.preview-font-large .preview-stat {
    font-size: 2rem;
}

.preview-font-small .preview-stat {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact .preview-body {
    padding: 0.5rem 0.75rem;
}

.preview-compact .preview-body p {
    margin-bottom: 0.25rem;
}

.preview-compact .preview-card {
    padding: 0.4rem 0.6rem;
}

/* === Toast === */
.settings-toast {
    position: fixed;
    top: 1rem;
    right: 1rem;
    z-index: 1100;
    animation: slideIn 0.3s ease-out;
}

@@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-1rem);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

