    padding: 0.75rem;
    border-radius: 6px;
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.preview-stat {
    font-size: 1.5rem;
    font-weight: 700;
    color: #0d6efd;
}

.preview-label {
    color: #6c757d;
    font-size: 0.85rem;
}

