.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-light .preview-header {
    background: #f8f9fa;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-theme-dark .preview-header {
    background: #181825;
    border-color: #45475a;
    color: #cdd6f4;
}

.preview-theme-dark .preview-card {
    background: #313244;
}

.preview-theme-dark .preview-label {
    color: #a6adc8;
}

.preview-theme-dark .btn-primary {
    background: #89b4fa;
    border-color: #89b4fa;
    color: #1e1e2e;
}

.preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
}

.preview-theme-system .preview-header {
    background: #f8f9fa;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 0.95rem;
}

.preview-font-large {
    font-size: 1.1rem;
}

.preview-font-large .preview-stat {
    font-size: 2rem;
}

.preview-font-small .preview-stat {
    font-size: 1.2rem;
